page_settings.custom_css:
/* ==== BLOG (padrao/blog) ==== */
/* cores e fontes do site (padrão Voucher Tec) */
:root{
  --blog-fundo:#FFFFFF;
  --blog-fundo-2:#F4F4F4;
  --blog-texto:#3C3D3D;
  --blog-texto-suave:#666666;
  --blog-titulo:#3C3D3D;
  --blog-acento:#E98300;
  --blog-acento-texto:#C56F00;
  --blog-fio:#E6E6E6;
  --blog-display:"Montserrat","Segoe UI",sans-serif;
  --blog-ui:"Roboto","Segoe UI",sans-serif;
  --blog-nav-h:0px;
  --blog-pad:max(16px,calc((100vw - 1140px) / 2));
  --blog-ease:cubic-bezier(.22,.61,.36,1);
  --blog-foto-filtro:none;
  --blog-capa-fundo:#3C3D3D;
  --blog-capa-filtro:brightness(.9);
  --blog-capa-scrim:linear-gradient(to top,rgba(0,0,0,.85) 0%,rgba(0,0,0,.45) 42%,rgba(0,0,0,.15) 74%,rgba(0,0,0,.45) 100%);
  --blog-capa-texto:#FFFFFF;
  --blog-capa-texto-suave:rgba(255,255,255,.75);
}
.blog-head .eyebrow{font-family:var(--blog-ui);font-size:12px;font-weight:600;letter-spacing:.28em;text-transform:uppercase;margin:0}
/* Blog padrão: estrutura igual em todo site; cores e fontes nas variáveis --blog-* do site. */
body.blog,body.archive,body.search,body.single-post,body.error404{background:var(--blog-fundo);color:var(--blog-texto)}
body.blog .site-main,body.archive .site-main,body.search .site-main,body.single-post .site-main{padding:0}

/* cabeçalho do arquivo (abaixo da barra fixa) */
.blog-head{background:var(--blog-fundo);color:var(--blog-texto);padding:0}
.blog-head-in{padding:calc(var(--blog-nav-h) + clamp(52px,7vw,96px)) var(--blog-pad) clamp(34px,4.5vw,56px);max-width:760px}
.blog-head h1{font-family:var(--blog-display);font-weight:400;font-size:clamp(34px,5vw,58px);line-height:1.08;color:var(--blog-titulo);margin:20px 0 16px}
.blog-head-in > p:not(.eyebrow){color:var(--blog-texto-suave);max-width:52ch;font-size:16.5px;line-height:1.6;margin:0}
.blog-head .eyebrow,.blog-cta .eyebrow{color:var(--blog-acento-texto)}

/* arquivo: grade de cards separados por fio de 1px */
.blog-grade{background:var(--blog-fundo);padding:0 var(--blog-pad) clamp(80px,11vw,140px)}
.blog-grade .elementor-posts{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;background:var(--blog-fio)}
.blog-grade .elementor-post{position:relative;background:var(--blog-fundo-2);margin:0;padding:0;border:0;border-radius:0;box-shadow:none;overflow:hidden;display:flex;flex-direction:column;transition:background .5s var(--blog-ease)}
.blog-grade .elementor-post::before{content:"";position:absolute;top:0;left:0;right:0;height:1px;background:var(--blog-acento);transform:scaleX(0);transform-origin:0 50%;z-index:3;transition:transform .55s var(--blog-ease)}
.blog-grade .elementor-post:hover,.blog-grade .elementor-post:focus-within{background:var(--blog-fundo)}
.blog-grade .elementor-post:hover::before,.blog-grade .elementor-post:focus-within::before{transform:scaleX(1)}
.blog-grade .elementor-post__thumbnail{border-radius:0;padding:0;margin:0;aspect-ratio:3/2;overflow:hidden}
.blog-grade .elementor-post__thumbnail img{width:100%;height:100%;object-fit:cover;display:block;filter:var(--blog-foto-filtro);transform:scale(1.001);transition:transform 1s var(--blog-ease)}
.blog-grade .elementor-post:hover .elementor-post__thumbnail img{transform:scale(1.045)}
.blog-grade .elementor-post__text{padding:32px 30px 36px;display:flex;flex-direction:column;flex:1;margin:0}
.blog-grade .elementor-post__title{font-family:var(--blog-display);font-weight:400;font-size:clamp(21px,2vw,26px);line-height:1.14;letter-spacing:-.018em;color:var(--blog-titulo);margin:0 0 14px}
.blog-grade .elementor-post__title a{color:var(--blog-titulo);font-family:inherit;font-size:inherit;font-weight:inherit;line-height:inherit;letter-spacing:inherit}
.blog-grade .elementor-post__meta-data{font-family:var(--blog-ui);font-size:10.5px;letter-spacing:.28em;text-transform:uppercase;color:var(--blog-acento-texto);margin:0 0 16px;border:0;padding:0}
.blog-grade .elementor-post__excerpt{margin:0 0 22px}
.blog-grade .elementor-post__excerpt p{font-size:15px;font-weight:400;line-height:1.6;color:var(--blog-texto-suave);max-width:46ch;margin:0}
.blog-grade .elementor-post__read-more{margin-top:auto;font-family:var(--blog-ui);font-size:11px;letter-spacing:.28em;text-transform:uppercase;color:var(--blog-acento-texto);border:0;padding:0;background:none}
.blog-grade .elementor-post__read-more::after{content:" \2192";color:var(--blog-acento)}
.blog-grade .elementor-pagination{margin-top:clamp(40px,5vw,64px);font-family:var(--blog-ui);font-size:12px;letter-spacing:.16em;text-transform:uppercase;color:var(--blog-texto-suave)}
.blog-grade .elementor-pagination .page-numbers.current{color:var(--blog-acento-texto)}
.blog-grade .elementor-posts-nothing-found{font-family:var(--blog-ui);color:var(--blog-texto-suave);padding:24px 0}

/* post: capa com a foto destacada */
.blog-capa{position:relative;min-height:clamp(360px,50vh,540px);background:var(--blog-capa-fundo);display:flex;flex-direction:column;justify-content:flex-end;overflow:hidden;padding:calc(var(--blog-nav-h) + 40px) var(--blog-pad) clamp(40px,5vw,64px);width:auto;max-width:none}
.blog-capa .elementor-widget-theme-post-featured-image{position:absolute;inset:0;margin:0;width:100%;z-index:0}
.blog-capa .elementor-widget-theme-post-featured-image .elementor-widget-container,
.blog-capa .elementor-widget-theme-post-featured-image figure,
.blog-capa .elementor-widget-theme-post-featured-image a{display:block;height:100%}
.blog-capa .elementor-widget-theme-post-featured-image img{width:100%;height:100%;object-fit:cover;display:block;border-radius:0;filter:var(--blog-capa-filtro)}
.blog-capa::after{content:"";position:absolute;inset:0;z-index:1;pointer-events:none;background:var(--blog-capa-scrim)}
.blog-capa > .elementor-widget-theme-post-title,.blog-capa > .elementor-widget-post-info{position:relative;z-index:2;width:100%}
.blog-capa .elementor-heading-title{font-family:var(--blog-display);font-weight:400;font-size:clamp(30px,5.4vw,64px);line-height:1.06;letter-spacing:-.022em;color:var(--blog-capa-texto);max-width:20ch;margin:0}
.blog-capa .elementor-post-info{margin-top:20px}
.blog-capa .elementor-post-info__item,.blog-capa .elementor-post-info span{font-family:var(--blog-ui);font-size:11px;letter-spacing:.28em;text-transform:uppercase;color:var(--blog-capa-texto-suave)}
.blog-capa .elementor-post-info__terms-list-item,.blog-capa .elementor-post-info__terms-list-item a{color:var(--blog-capa-texto)}
.blog-capa .elementor-inline-item::after{color:var(--blog-acento)}
.blog-capa .elementor-icon-list-icon{display:none}

/* post: texto + barra lateral */
.blog-corpo{background:var(--blog-fundo);color:var(--blog-texto);padding:clamp(56px,7vw,92px) var(--blog-pad) clamp(70px,9vw,120px);display:grid;grid-template-columns:minmax(0,1fr) 268px;gap:clamp(40px,6vw,88px);align-items:start;width:auto;max-width:1280px;margin:0 auto}
.blog-corpo > .e-con{width:auto;max-width:none;padding:0}
.blog-texto h2{font-family:var(--blog-display);font-weight:400;font-size:clamp(24px,3vw,34px);line-height:1.12;letter-spacing:-.018em;color:var(--blog-titulo);margin:44px 0 16px}
.blog-texto h3{font-family:var(--blog-display);font-weight:400;font-size:clamp(20px,2.3vw,26px);line-height:1.2;color:var(--blog-titulo);margin:32px 0 12px}
.blog-texto h2:first-child,.blog-texto h3:first-child{margin-top:0}
.blog-texto p,.blog-texto li{font-size:16.5px;font-weight:400;line-height:1.66;color:var(--blog-texto)}
.blog-texto p{margin:0 0 20px}
.blog-texto ul,.blog-texto ol{margin:0 0 20px 1.2em;padding:0}
.blog-texto ul{list-style:disc}
.blog-texto ol{list-style:decimal}
.blog-texto li{margin:0 0 8px}
.blog-texto strong{font-weight:600;color:var(--blog-titulo)}
.blog-texto a:not(.btn){color:var(--blog-acento-texto);border-bottom:1px solid var(--blog-acento)}
.blog-texto img{max-width:100%;height:auto;border-radius:0}
.blog-lado{position:sticky;top:calc(var(--blog-nav-h) + 24px)}
.blog-lado h4,.blog-lado .elementor-widget-wp-widget-categories h5{font-family:var(--blog-ui);font-size:11px;font-weight:500;letter-spacing:.3em;text-transform:uppercase;color:var(--blog-acento-texto);margin:0 0 18px}
.blog-busca{display:flex;align-items:center;gap:10px;border-bottom:1px solid var(--blog-fio);padding-bottom:10px;margin-bottom:38px}
.blog-busca input{flex:1;min-width:0;border:0;border-radius:0;background:none;box-shadow:none;font-family:var(--blog-ui);font-size:15px;color:var(--blog-texto);padding:6px 0;outline:none}
.blog-busca input::placeholder{color:var(--blog-texto-suave)}
.blog-busca button,.blog-busca button:hover,.blog-busca button:focus{border:0;border-radius:0;background:none;padding:0;cursor:pointer;color:var(--blog-acento);font-family:var(--blog-ui);font-size:16px;line-height:1}
.blog-busca:focus-within{border-bottom-color:var(--blog-acento)}
.blog-lado ul{list-style:none;margin:0;padding:0}
.blog-lado li{margin:0;border-bottom:1px solid var(--blog-fio)}
.blog-lado li a{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:12px 0;font-family:var(--blog-ui);font-size:14.5px;color:var(--blog-texto);transition:color .3s}
.blog-lado li a::after{content:"\2192";color:var(--blog-acento);opacity:0;transform:translateX(-6px);transition:opacity .35s var(--blog-ease),transform .35s var(--blog-ease)}
.blog-lado li a:hover{color:var(--blog-acento-texto)}
.blog-lado li a:hover::after{opacity:1;transform:none}

/* post: convite do fim */
.blog-cta{background:var(--blog-fundo-2);color:var(--blog-texto);padding:clamp(52px,7vw,86px) var(--blog-pad);text-align:center}
.blog-cta-in{max-width:640px;margin:0 auto}
.blog-cta h3{font-family:var(--blog-display);font-weight:400;font-size:clamp(24px,3.2vw,38px);line-height:1.1;color:var(--blog-titulo);margin:18px 0 14px}
.blog-cta-in > p:not(.eyebrow){color:var(--blog-texto-suave);max-width:46ch;margin:0 auto 30px;font-size:16px;font-weight:400;line-height:1.6}

@media(max-width:1060px){
  .blog-grade .elementor-posts{grid-template-columns:repeat(2,1fr)}
  .blog-corpo{grid-template-columns:1fr;gap:clamp(44px,6vw,64px)}
  .blog-lado{position:static}
}
@media(max-width:700px){
  .blog-grade .elementor-posts{grid-template-columns:1fr}
  .blog-head-in{padding-top:calc(var(--blog-nav-h) + 40px)}
  .blog-capa{padding-top:calc(var(--blog-nav-h) + 28px)}
body.tt-topo-transparente .blog-capa{--blog-nav-h:96px}
@media (max-width:1024px){body.tt-topo-transparente .blog-capa{--blog-nav-h:80px}}
  .blog-grade .elementor-post__text{padding:26px 22px 30px}
}
/* ==== /BLOG ==== */
/* tela larga: a margem esquerda entra na largura máxima */
.blog-head-in{max-width:calc(760px + var(--blog-pad))}
/* chamada final do post: botão e eyebrow (o kit deixa a classe .btn para o site) */
.blog-cta .eyebrow{font-family:var(--blog-ui);font-size:12px;font-weight:600;letter-spacing:.28em;text-transform:uppercase;margin:0}
.blog-cta .btn{display:inline-block;padding:16px 34px;border-radius:8px;background:#E98300;color:#FFFFFF;font-family:Montserrat,sans-serif;font-size:14px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;text-decoration:none;transition:background .25s,transform .25s}
.blog-cta .btn:hover{background:#3C3D3D;color:#FFFFFF;transform:translateY(-2px)}
